// ui_mouse_inside_rect_with_padding @ 0x00403430
// returns 1 when the mouse is inside an expanded rect (x-10,y-2..x+w,y+h) and capture is clear
int ui_mouse_inside_rect_with_padding(float *xy, int h, int w)
{
  return *xy - 10.0 < ui_mouse_x
      && xy[1] - 2.0 < ui_mouse_y
      && (double)w + *xy > ui_mouse_x
      && (double)h + xy[1] > ui_mouse_y
      && !ui_mouse_blocked;
}

// ui_mouse_inside_rect @ 0x004034A0
// returns 1 when the mouse is inside the rect and mouse capture is clear
int ui_mouse_inside_rect(float *xy, int h, int w)
{
  return ui_mouse_x > (double)*xy
      && ui_mouse_y > (double)xy[1]
      && (double)w + *xy > ui_mouse_x
      && (double)h + xy[1] > ui_mouse_y
      && !ui_mouse_blocked;
}

