// bonus_label_for_entry @ 0x00429580
// returns the label string for a bonus entry (formatting weapon/score cases)
char *bonus_label_for_entry(bonus_entry_t *bonus_entry)
{
  bonus_id_t bonus_id; // eax
  char *v2; // eax

  bonus_id = bonus_entry->bonus_id;
  if ( bonus_entry->bonus_id == BONUS_ID_WEAPON )
  {
    v2 = weapon_table_entry(bonus_entry->time.amount);
    crt_sprintf(bonus_label_format_buffer, "%s", v2);
    return bonus_label_format_buffer;
  }
  else if ( bonus_id == BONUS_ID_POINTS )
  {
    crt_sprintf(bonus_label_format_buffer, "%s: %d", (const char *)bonus_label_points, bonus_entry->time.amount);
    return bonus_label_format_buffer;
  }
  else
  {
    return *(&bonus_meta_table.label + 5 * bonus_id);
  }
}

