// ui_menu_main_click_mods @ 0x00447350
// main menu MODS click callback (sets ui_transition_direction=0 and game_state_pending=0x14)
void ui_menu_main_click_mods()
{
  ui_transition_direction = 0;
  game_state_pending = GAME_STATE_MODS_MENU;
}

// ui_menu_main_click_options @ 0x00447370
// main menu OPTIONS click callback (sets ui_transition_direction=0 and game_state_pending=2)
void ui_menu_main_click_options()
{
  ui_transition_direction = 0;
  game_state_pending = GAME_STATE_OPTIONS_MENU;
}

// ui_menu_main_click_statistics @ 0x00447390
// main menu STATISTICS click callback (queues state 4 and switches menu music to shortie)
void ui_menu_main_click_statistics()
{
  ui_transition_direction = 0;
  game_state_pending = GAME_STATE_STATISTICS_MENU;
  sfx_mute_all(music_track_crimson_theme_id);
  sfx_mute_all(music_track_shortie_monk_id);
  sfx_mute_all(music_track_extra_0);
  sfx_play_exclusive(music_track_shortie_monk_id);
}

// ui_menu_main_click_controls @ 0x004473E0
// main menu CONTROLS click callback (sets ui_transition_direction=0 and game_state_pending=3)
void ui_menu_main_click_controls()
{
  ui_transition_direction = 0;
  game_state_pending = GAME_STATE_CONTROLS_MENU;
}

// ui_menu_main_click_play_game @ 0x00447400
// main menu PLAY GAME click callback (sets ui_transition_direction=0 and game_state_pending=1)
void ui_menu_main_click_play_game()
{
  ui_transition_direction = 0;
  game_state_pending = GAME_STATE_PLAY_GAME_MENU;
}

// ui_menu_click_back_contextual @ 0x00447420
// menu BACK callback: sets transition and routes to state 0 (main menu) or state 5 (in-game menu context)
int ui_menu_click_back_contextual()
{
  int result; // eax

  LOBYTE(result) = plugin_runtime_active_latch;
  ui_transition_direction = 0;
  if ( plugin_runtime_active_latch )
  {
    game_state_pending = GAME_STATE_PAUSE_MENU;
  }
  else
  {
    result = render_pass_mode != 0 ? 5 : 0;
    game_state_pending = result;
  }
  return result;
}

// ui_menu_main_click_quit @ 0x00447450
// main menu QUIT click callback (clears ui_sign_crimson_update_disabled, sets ui_transition_direction=0, game_state_pending=10, mutes music)
void ui_menu_main_click_quit()
{
  game_state_pending = GAME_STATE_QUIT_TRANSITION;
  ui_sign_crimson.focus_disabled = 0;
  ui_transition_direction = 0;
  sfx_mute_all(music_track_crimson_theme_id);
  sfx_mute_all(music_track_extra_0);
  sfx_mute_all(music_track_shortie_monk_id);
}

// ui_menu_pause_click_resume @ 0x00447490
// pause menu RESUME callback: queues gameplay/Typ-o resume, or plugin runtime when opened from plugin pause context
void ui_menu_pause_click_resume()
{
  if ( plugin_interface_ptr )
    plugin_interface_ptr->parms.fields.onPause = 0;
  ui_sign_crimson.focus_disabled = 0;
  ui_transition_direction = 0;
  game_state_pending = plugin_runtime_active_latch != 0 ? GAME_STATE_PLUGIN_RUNTIME : GAME_STATE_GAMEPLAY;
  if ( config_blob.game_mode == GAME_MODE_TYPO_SHOOTER )
    game_state_pending = GAME_STATE_TYPO_GAMEPLAY;
}

// ui_menu_pause_click_main_menu @ 0x004474E0
// pause menu MAIN MENU callback: exits plugin runtime if active, then returns to main menu/mods and restores menu music
void ui_menu_pause_click_main_menu()
{
  if ( plugin_interface_ptr )
  {
    plugin_interface_ptr->parms.fields.onPause = 0;
    plugin_runtime_active_latch = 0;
    ((void (__thiscall *)(mod_interface_t *))plugin_interface_ptr->vtable->Shutdown)(plugin_interface_ptr);
    sfx_mute_all(music_track_extra_0);
    plugin_interface_ptr = nullptr;
    FreeLibrary(plugin_module_handle);
    plugin_module_handle = nullptr;
    plugin_runtime_needs_init = 1;
    game_state_pending = GAME_STATE_MODS_MENU;
  }
  else
  {
    game_state_pending = GAME_STATE_MAIN_MENU;
  }
  ui_transition_direction = 0;
  render_pass_mode = 0;
  sfx_mute_all(music_track_crimson_theme_id);
  sfx_mute_all(music_track_shortie_monk_id);
  sfx_mute_all(music_track_extra_0);
  sfx_play_exclusive(music_track_crimson_theme_id);
}

